const EXPECTED = [0, 0.28, 0.16, 0.11, 0.08, 0.065, 0.05, 0.04, 0.033, 0.028, 0.025, 0.018, 0.016, 0.014, 0.012, 0.011, 0.01, 0.009, 0.008, 0.007, 0.006];
const exp = p => EXPECTED[Math.min(20, Math.max(1, Math.round(p)))] || 0.005;

// Keep queries ranking in the striking-distance band, score the extra clicks a move to position 3 would bring, group by page
const cfg = $('Set report settings').first().json;
const brand = String(cfg.brand_terms || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const rows = ($json.rows || []).map(r => ({ query: r.keys[0], page: r.keys[1], clicks: r.clicks, impressions: r.impressions, ctr: r.ctr, position: r.position }))
  .filter(r => r.position >= Number(cfg.min_position) && r.position <= Number(cfg.max_position) && r.impressions >= Number(cfg.min_impressions)
    && !brand.some(b => r.query.toLowerCase().includes(b)));
for (const r of rows) r.potential = Math.max(0, Math.round(r.impressions * (exp(3) - r.ctr)));
const pages = {};
for (const r of rows) (pages[r.page] = pages[r.page] || []).push(r);
const out = Object.entries(pages).map(([page, qs]) => {
  qs.sort((a, b) => b.potential - a.potential);
  const top = qs.slice(0, 8);
  return { page, main_query: top[0].query, potential_clicks: top.reduce((s, q) => s + q.potential, 0),
    impressions: top.reduce((s, q) => s + q.impressions, 0), clicks: top.reduce((s, q) => s + q.clicks, 0),
    best_position: Math.min(...top.map(q => q.position)).toFixed(1),
    queries: top.map(q => `${q.query} (pos ${q.position.toFixed(1)}, ${q.impressions} impr, ${(q.ctr * 100).toFixed(1)}% CTR)`) };
}).sort((a, b) => b.potential_clicks - a.potential_clicks).slice(0, Number(cfg.max_pages) || 5);
if (!out.length) return [{ json: { none: true, rows_checked: ($json.rows || []).length } }];
return out.map(json => ({ json: { none: false, ...json } }));

// Read what the page already covers so the brief improves it instead of repeating it
const opps = $('Find striking-distance keywords').all();
return $input.all().map((it, i) => {
  const o = opps[i].json;
  const html = String(it.json.body ?? it.json.data ?? '');
  const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16))).replace(/&#(\d+);/g, (m, d) => String.fromCharCode(Number(d))).replace(/\s+/g, ' ').trim();
  const title = strip((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
  const meta = strip((html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)/i) || [])[1]);
  const h1 = strip((html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i) || [])[1]);
  const h2s = (html.match(/<h2\b[^>]*>[\s\S]*?<\/h2>/gi) || []).map(strip).filter(Boolean).slice(0, 15);
  const body = strip((html.match(/<body[^>]*>([\s\S]*)<\/body>/i) || [, html])[1].replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<(nav|footer)\b[\s\S]*?<\/\1>/gi, ' '));
  const words = body ? body.split(' ').length : 0;
  const lower = body.toLowerCase();
  const coverage = o.queries.map(q => { const k = q.split(' (pos')[0]; return `${k}: ${title.toLowerCase().includes(k) ? 'in title' : lower.includes(k) ? 'in body only' : 'NOT on page'}`; });
  return { json: { ...o, page_loaded: Number(it.json.statusCode) === 200, title, meta_description: meta, h1, h2s, words, coverage, excerpt: body.slice(0, 1500) } };
});

parameters.text:
=You are an SEO content strategist. This page already ranks on Google's first or second page for the queries below. Write a brief to improve THIS page (not a new article) so it can move into the top 3.

Page: {{ $json.page }}
Current title: {{ $json.title }}
Current meta description: {{ $json.meta_description }}
H1: {{ $json.h1 }}
H2s: {{ $json.h2s.join(' | ') }}
Word count: {{ $json.words }}
Queries (last 28 days): {{ $json.queries.join('; ') }}
Where the queries appear: {{ $json.coverage.join('; ') }}
Opening content: {{ $json.excerpt }}

Rules:
- primary_keyword is the query with the most potential; search_intent is informational, commercial, transactional or navigational.
- recommended_title 30-60 characters, recommended_meta_description 120-155 characters, both containing the primary keyword naturally.
- h2_outline: the full improved H2 structure (keep good existing H2s, add missing ones), max 10.
- missing_subtopics: what searchers for these queries expect that the page lacks, max 6.
- faq_questions: 3-5 real questions to answer on the page.
- quick_wins: 2-4 edits that take under 15 minutes.
- Do not invent statistics, prices or claims about the business.

