{
  "primary_keyword": "boiler service cost",
  "search_intent": "commercial",
  "recommended_title": "Boiler Service Cost in 2026: Prices, What's Included and Tips",
  "recommended_meta_description": "How much does a boiler service cost? See typical prices, what an engineer checks and how to book.",
  "h2_outline": [
    "How much does a boiler service cost?",
    "What is included in a service"
  ],
  "missing_subtopics": [
    "Price by boiler type"
  ],
  "faq_questions": [
    "How often should a boiler be serviced?"
  ],
  "quick_wins": [
    "Add the main keyword to the H1"
  ],
  "estimated_effort": "1-2 hours"
}
